                   Divider()                    HStack {                        Text("Total").bold()                        Spacer()                        Text("$\(totalCharge, specifier: "%.2f")").bold()                    }                }                .padding()                .background(Color(UIColor.secondarySystemBackground))                .cornerRadius(12)                                if let error = paymentController.errorMessage {                    Text(error)                        .foregroundColor(.red)                        .font(.caption)                }            }            .padding()        }        .navigationTitle("Review Order")        .navigationBarTitleDisplayMode(.inline)        .safeAreaInset(edge: .bottom) {            VStack {                if let paymentSheet = paymentController.paymentSheet {                    PaymentSheet.PaymentButton(                        paymentSheet: paymentSheet,                        onCompletion: handlePaymentResult                    ) {                        Text("Pay & Post Request")                            .font(.headline)                            .foregroundColor(.white)                            .frame(maxWidth: .infinity)                            .padding()                            .background(Color.orange)                            .cornerRadius(14)                    }                } else if paymentController.isLoading {                    ProgressView("Loading payment...")                        .frame(maxWidth: .infinity)                        .padding()                } else {                    Button {                        Task {                            await paymentController.preparePaymentSheet(amount: totalCharge)                        }                    } label: {                        Text("Retry Payment Setup")                            .font(.headline)                            .foregroundColor(.white)                            .frame(maxWidth: .infinity)                            .padding()                            .background(Color.orange)                            .cornerRadius(14)                    }                }            }            .padding()            .background(Color(UIColor.systemBackground))        }        .onAppear {            Task {                await paymentController.preparePaymentSheet(amount: totalCharge)            }        }    }        func handlePaymentResult(_ result: PaymentSheetResult) {        switch result {        case .completed:            postOrderToFirebase()        case .canceled:            break        case .failed(let error):            paymentController.errorMessage = error.localizedDescription        }    }        func postOrderToFirebase() {        let newOrder = Order(            requesterId: Auth.auth().currentUser?.uid ?? "anonymous",            fulfillerId: "",            restaurantName: restaurantName,            orderDetails: items.map { $0.name },            pickupName: nil,            estimatedTime: nil,            foodCost: foodCost,            bountyAmount: bounty,            grubhubOrderId: "",            status: "open",            proofImageUrl: ""        )                let db = Firestore.firestore()        do {            try db.collection("orders").addDocument(from: newOrder) { error in                if let error = error {                    print("Error saving order: \(error.localizedDescription)")                } else {                    print("Order successfully posted!")                    menuManager.bag.removeAll()                    menuManager.currentRestaurantID = nil                    dismiss()                }            }        } catch {            print("Error encoding order: \(error.localizedDescription)")        }    }}